// --- KONFIGURASI ---
const CONFIG = {
    CSV_URL: "https://docs.google.com/spreadsheets/d/e/2PACX-1vQ_0-HrBEJTG1vfHycGRu6oP9h4UaAgq7j70gskW9SriVSphZQB5DoXAiSSPrqNPEg-VCRiefvNDjLV/pub?gid=0&single=true&output=csv",
    CACHE_KEY: "skenpat_jadwal_v3",
    DAYS: ["Senin", "Selasa", "Rabu", "Kamis", "Jumat"],
    MAJOR_COLORS: ['#FF9F43', '#FF6B6B', '#48DBFB', '#5F27CD', '#1DD1A1', '#FECA57', '#54a0ff']
};

// --- STATE MANAGEMENT ---
const state = {
    allData: [],
    isLoading: true,
    currentKelas: null
};

// --- DOM ELEMENTS ---
const elements = {
    loader: document.getElementById('loader'),
    homeView: document.getElementById('homeView'),
    scheduleView: document.getElementById('scheduleView'),
    pageTitle: document.getElementById('pageTitle'),
    pageSubtitle: document.getElementById('pageSubtitle'),
    mobileNav: document.getElementById('mobileNav'),
    kelasGrid: document.getElementById('kelasGrid'),
    scheduleContent: document.getElementById('scheduleContent'),
    kelasSwitcher: document.getElementById('kelasSwitcher')
};

// --- HELPERS ---

/**
 * Membersihkan string dan memastikan format huruf konsisten
 */
function sanitize(str) {
    return str ? str.toString().trim() : '';
}

/**
 * Deteksi Jurusan dari nama kelas (contoh: x_rpl_1 -> 'rpl')
 */
function getMajorCode(kelasName) {
    if (!kelasName) return 'umum';
    // Normalisasi: lowercase, ganti spasi/petak dengan underscore
    const normalized = kelasName.toLowerCase().replace(/[\s-]+/g, '_'); 
    const parts = normalized.split('_');
    
    // Format fleksibel: mencoba mencari kata kunci jurusan di posisi manapun
    const keywords = ['rpl', 'dpb', 'ulw', 'seni', 'htl', 'boga', 'kct', 'tkj', 'bdp'];
    const found = parts.find(p => keywords.includes(p));
    
    return found || (parts.length >= 2 ? parts[1] : 'umum');
}

function getMajorDisplay(majorCode) {
    const map = {
        'rpl': 'Rekayasa Perangkat Lunak',
        'dpb': 'Desain & Produksi Busana',
        'ulw': 'Usaha Layanan Wisata',
        'seni': 'Seni Musik',
        'htl': 'Akomodasi Perhotelan',
        'boga': 'Kuliner',
        'kct': 'Tata Kecantikan',
        'tkj': 'Teknik Komputer Jaringan',
        'bdp': 'Bisnis Daring Pemasaran'
    };
    return map[majorCode] || majorCode.toUpperCase();
}

function getIconForMajor(majorCode) {
    const map = {
        'rpl': 'fa-laptop-code',
        'dpb': 'fa-mitten',
        'ulw': 'fa-person-walking-luggage',
        'seni': 'fa-palette',
        'htl': 'fa-hotel',
        'boga': 'fa-utensils',
        'kct': 'fa-hand-sparkles',
        'tkj': 'fa-network-wired',
        'bdp': 'fa-store'
    };
    return map[majorCode] || 'fa-book-open';
}

// --- INIT ---
document.addEventListener('DOMContentLoaded', async () => {
    initEventListeners();
    await fetchData();
    handleRouting();
});

// --- EVENT LISTENERS ---
function initEventListeners() {
    // Listener untuk dropdown switcher kelas (Delegasi Event)
    if (elements.kelasSwitcher) {
        elements.kelasSwitcher.addEventListener('change', (e) => {
            if (e.target.value) {
                updateURLParam('kelas', e.target.value);
            }
        });
    }
}

function updateURLParam(key, value) {
    const url = new URL(window.location);
    url.searchParams.set(key, value);
    window.location.href = url.toString();
}

// --- FITUR: FORCE REFRESH ---
window.forceRefresh = function() {
    const konfirmasi = confirm("Yakin ingin reset cache? Website akan memuat ulang data dari server.");
    if (konfirmasi) {
        localStorage.removeItem(CONFIG.CACHE_KEY);
        location.reload();
    }
};

// --- DATA FETCHING (OFFLINE FIRST LOGIC) ---
async function fetchData() {
    // 1. Cek Cache
    const cached = localStorage.getItem(CONFIG.CACHE_KEY);
    if (cached) {
        try {
            state.allData = JSON.parse(cached);
            console.log("✅ Menggunakan data cache.");
            state.isLoading = false; // Data siap, loader bisa disembunyikan nanti di router
        } catch (e) {
            console.error("Cache rusak:", e);
        }
    }

    // 2. Fetch Online (Background Update)
    try {
        // Cek apakah library PapaParse ada
        if (typeof Papa === 'undefined') {
            throw new Error("Library PapaParse tidak ditemukan.");
        }

        const response = await fetch(CONFIG.CSV_URL);
        if (!response.ok) throw new Error("Gagal koneksi ke server.");

        const csvText = await response.text();
        const parsed = Papa.parse(csvText, { header: true });
        
        // Sanitasi dan Filter Data
        const newData = parsed.data
            .map(row => ({
                kelas: sanitize(row.kelas),
                hari: sanitize(row.hari),
                mapel: sanitize(row.mapel),
                jam: sanitize(row.jam),
                guru: sanitize(row.guru),
                batas: sanitize(row.batas)
            }))
            .filter(row => row.kelas && row.hari && row.mapel);

        if (newData.length > 0) {
            localStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify(newData));
            state.allData = newData;
            console.log("🌐 Data berhasil diupdate dari server.");
            
            // Jika sedang membuka view, refresh view untuk data baru
            const params = new URLSearchParams(window.location.search);
            const currentKelas = params.get('kelas');
            if (currentKelas) {
                renderScheduleView(currentKelas);
            } else if (!state.isLoading) {
                renderHomeView();
            }
        }
    } catch (error) {
        console.error("Gagal fetch online:", error);
        if (state.allData.length === 0) {
            showErrorUI("Gagal memuat data. Periksa koneksi internet atau coba Reset Data.");
        }
    } finally {
        // Matikan loader setelah proses awal selesai (baik sukses maupun gagal fetch, asal ada cache)
        if (state.allData.length > 0) {
            elements.loader.classList.add('hidden');
        }
    }
}

function showErrorUI(message) {
    elements.loader.innerHTML = `
        <div style="text-align:center; color: #ff6b6b; padding: 20px;">
            <i class="fa-solid fa-triangle-exclamation" style="font-size: 3rem; margin-bottom: 10px;"></i>
            <p>${message}</p>
            <button onclick="forceRefresh()" style="margin-top:10px; padding: 8px 16px; cursor:pointer;">Coba Lagi</button>
        </div>
    `;
}

// --- ROUTING ---
function handleRouting() {
    if (state.isLoading) return; // Tunggu fetch pertama selesai

    const params = new URLSearchParams(window.location.search);
    const kelasParam = params.get('kelas');

    if (kelasParam) {
        state.currentKelas = kelasParam;
        renderScheduleView(kelasParam);
    } else {
        state.currentKelas = null;
        renderHomeView();
    }
}

// --- RENDER HOME VIEW ---
function renderHomeView() {
    elements.homeView.classList.remove('hidden');
    elements.scheduleView.classList.remove('active');
    elements.mobileNav.classList.add('hidden');

    elements.pageTitle.textContent = "Mapel Kelas X 📚";
    elements.pageSubtitle.textContent = "Pilih jurusanmu, lalu pilih kelas!";
    elements.kelasGrid.innerHTML = '';

    // Group Data
    const majorGroups = {};
    state.allData.forEach(d => {
        const major = getMajorCode(d.kelas);
        if (!majorGroups[major]) majorGroups[major] = new Set();
        majorGroups[major].add(d.kelas);
    });

    const sortedMajors = Object.keys(majorGroups).sort();

    if (sortedMajors.length === 0) {
        elements.kelasGrid.innerHTML = '<p style="text-align:center;">Data tidak tersedia.</p>';
        return;
    }

    const fragment = document.createDocumentFragment();

    sortedMajors.forEach((major, index) => {
        const kelasList = Array.from(majorGroups[major]).sort((a, b) => {
            return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
        });

        const color = CONFIG.MAJOR_COLORS[index % CONFIG.MAJOR_COLORS.length];
        const displayName = getMajorDisplay(major);
        const icon = getIconForMajor(major);

        const card = document.createElement('div');
        card.className = 'jurusan-card';
        
        // Build HTML string
        let optionsHtml = `<option value="" disabled selected>-- Pilih --</option>`;
        kelasList.forEach(k => {
            const displayKelas = k.toUpperCase().replace(/_/g, ' ');
            optionsHtml += `<option value="${k}">${displayKelas}</option>`;
        });

        card.innerHTML = `
          <div class="jurusan-header" style="background-color: ${color}">
            <h2><i class="fa-solid ${icon}"></i> ${displayName}</h2>
          </div>
          <div class="jurusan-content">
            <p style="margin-bottom: 0.5rem; font-size: 0.9rem; color: #777;">Pilih Kelas:</p>
            <div class="kelas-select-wrapper">
              <select class="kelas-select" data-major="${major}">
                ${optionsHtml}
              </select>
            </div>
          </div>
        `;
        fragment.appendChild(card);
    });

    elements.kelasGrid.appendChild(fragment);

    // Event Listener untuk Select Dropdown di Home
    document.querySelectorAll('.kelas-select').forEach(select => {
        select.addEventListener('change', (e) => {
            updateURLParam('kelas', e.target.value);
        });
    });
}

// --- RENDER SCHEDULE VIEW ---
function renderScheduleView(kelas) {
    elements.homeView.classList.add('hidden');
    elements.scheduleView.classList.add('active');

    // Judul
    elements.pageTitle.textContent = `Jadwal ${kelas.replace(/_/g, ' ').toUpperCase()}`;
    elements.pageSubtitle.textContent = "Semester 2 - 2025/2026";

    // Populate Switcher
    const allKelas = [...new Set(state.allData.map(d => d.kelas))].sort((a, b) => {
        return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
    });

    elements.kelasSwitcher.innerHTML = '<option value="">Pindah Kelas Cepat...</option>';
    allKelas.forEach(k => {
        const opt = document.createElement('option');
        opt.value = k;
        opt.textContent = k.toUpperCase();
        if (k === kelas) opt.selected = true;
        elements.kelasSwitcher.appendChild(opt);
    });

    // Filter & Group Data
    const kelasData = state.allData.filter(d => d.kelas === kelas);
    const groupedByDay = kelasData.reduce((acc, curr) => {
        if (!acc[curr.hari]) acc[curr.hari] = [];
        acc[curr.hari].push(curr);
        return acc;
    }, {});

    elements.scheduleContent.innerHTML = '';
    const fragment = document.createDocumentFragment();

    CONFIG.DAYS.forEach(day => {
        if (groupedByDay[day]) {
            const dayData = groupedByDay[day].sort((a, b) => parseInt(a.jam) - parseInt(b.jam));
            
            const dayCard = document.createElement('div');
            dayCard.className = 'day-card scroll-section'; // Tambah class scroll-section untuk observer
            dayCard.dataset.day = day; // ID untuk observer

            let listHTML = '';
            dayData.forEach(item => {
                const lowerMapel = item.mapel.toLowerCase();
                
                if (lowerMapel.includes('istirahat')) {
                    listHTML += `
                <li class="subject-item break">
                   <div style="display:flex; flex-direction:column; align-items:center;">
                    <span>${item.mapel.toUpperCase()}</span>
                    <span style="font-size: 0.8rem; font-weight: normal; opacity: 0.8;">${item.batas || ''}</span>
                    <span style="font-size: 0.8rem; font-weight: normal; opacity: 0.8;">(${item.guru})</span>
                   </div>
                </li>`;
                } else if (lowerMapel.includes('upacara')) {
                    listHTML += `
                <li class="subject-item upacara">
                  <div class="subject-time" style="background:#BBDEFB; border-color:#1565C0;">Ke-${item.jam}</div>
                  <div class="subject-info">
                    <span class="subject-name">${item.mapel}</span>
                    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap;">
                        <span class="subject-teacher">${item.guru || '-'}</span>
                        <span class="subject-limit"><i class="fa-regular fa-clock"></i> ${item.batas || '-'}</span>
                    </div>
                  </div>
                </li>`;
                } else {
                    listHTML += `
                <li class="subject-item">
                  <div class="subject-time">Ke-${item.jam}</div>
                  <div class="subject-info">
                    <span class="subject-name">${item.mapel}</span>
                    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap;">
                        <span class="subject-teacher">${item.guru || '-'}</span>
                        <span class="subject-limit"><i class="fa-regular fa-clock"></i> ${item.batas || '-'}</span>
                    </div>
                  </div>
                </li>`;
                }
            });

            dayCard.innerHTML = `
            <div class="day-header" id="header-${day}">${day.toUpperCase()}</div>
            <ul class="subject-list">${listHTML}</ul>
          `;
            fragment.appendChild(dayCard);
        }
    });

    elements.scheduleContent.appendChild(fragment);
    
    // Setup Mobile Nav & Scroll Spy
    renderMobileNav(CONFIG.DAYS);
    initScrollSpy();
    
    // Scroll ke top jika baru pindah halaman
    if (window.scrollY > 100) {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }
}

// --- NAVIGATION & SCROLL SPY ---

function renderMobileNav(days) {
    elements.mobileNav.innerHTML = '';
    
    days.forEach(day => {
        // Hanya render tombol jika hari tersebut ada di jadwal
        const headerExists = document.getElementById(`header-${day}`);
        if(!headerExists) return;

        const btn = document.createElement('button');
        btn.className = 'mobile-nav-btn';
        btn.dataset.target = day;
        btn.innerHTML = `<i class="fa-regular fa-calendar"></i> ${day.substring(0, 3)}`;
        
        btn.onclick = () => {
            const target = document.getElementById(`header-${day}`);
            if (target) {
                const headerOffset = 80;
                const elementPosition = target.getBoundingClientRect().top;
                const offsetPosition = elementPosition + window.pageYOffset - headerOffset;
                window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
            }
        };
        elements.mobileNav.appendChild(btn);
    });
    
    elements.mobileNav.classList.remove('hidden');
}

/**
 * Intersection Observer untuk menyorot (highlight) tombol navigasi mobile
 * sesuai dengan jadwal yang sedang dilihat user.
 */
function initScrollSpy() {
    const observerOptions = {
        root: null,
        rootMargin: '-20% 0px -60% 0px', // Trigger saat elemen di tengah viewport
        threshold: 0
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const day = entry.target.dataset.day;
                updateActiveNavButton(day);
            }
        });
    }, observerOptions);

    const sections = document.querySelectorAll('.scroll-section');
    sections.forEach(section => observer.observe(section));
}

function updateActiveNavButton(activeDay) {
    document.querySelectorAll('.mobile-nav-btn').forEach(btn => {
        if (btn.dataset.target === activeDay) {
            btn.classList.add('active');
        } else {
            btn.classList.remove('active');
        }
    });
}
